import { useEffect, useState } from 'react';
import type { GameId } from './pokemonData';

/**
 * Wild-encounter dataset generated by `scripts/fetchEncounters.mjs` from
 * PokéAPI and stored as a static bundle in `public/data/encounters.json`.
 * Shape: { [pokemonId]: { [gameId]: { [locationAreaName]: RawEncounterDetail[] } } }
 * Compact detail keys keep the payload small:
 *   m: method · c: chance % · l: [minLevel, maxLevel] · v: version[]
 */
/** Compact detail row straight from the JSON bundle. */
interface RawEncounterDetail {
  m: string;
  c: number;
  l: [number, number];
  v: string[];
  /** Optional encounter condition values (weather, time of day, swarms…). */
  cd?: string[];
}
/** Per game: location-area name → detail rows. */
export type RawGameEncounters = Record<string, RawEncounterDetail[]>;
export type EncounterDataset = Record<
  string,
  Partial<Record<GameId, RawGameEncounters>>
>;

export interface EncounterDetail {
  method: string;
  chance: number;
  minLevel: number;
  maxLevel: number;
  versions: string[];
  conditions: string[];
}
export interface EncounterArea {
  area: string;
  details: EncounterDetail[];
}

let cache: Promise<EncounterDataset | null> | null = null;

/** Lazy-load the encounter bundle once per session; null when unavailable. */
export function loadEncounterDataset(): Promise<EncounterDataset | null> {
  if (!cache) {
    cache = fetch('/data/encounters.json')
      .then((res) => (res.ok ? res.json() : null))
      .then((raw: unknown) => {
        if (!raw || typeof raw !== 'object') return null;
        return raw as EncounterDataset;
      })
      .catch(() => {
        cache = null; // allow retry on next call
        return null;
      });
  }
  return cache;
}

export function getEncountersForGame(
  dataset: EncounterDataset | null,
  pokemonId: number,
  gameId: GameId
): EncounterArea[] | null {
  if (!dataset) return null;
  const byGame = dataset[pokemonId];
  if (!byGame) return null;
  const raw = byGame[gameId];
  if (!raw) return null;
  const areas = Object.entries(raw).map(([area, details]) => ({
    area,
    details: details.map((d) => ({
      method: d.m,
      chance: d.c,
      minLevel: d.l[0],
      maxLevel: d.l[1],
      versions: d.v,
      conditions: d.cd ?? [],
    })),
  }));
  return areas.length > 0 ? areas : null;
}

/**
 * Encounter-condition families the UI surfaces (weather, time of day,
 * seasons, swarms, radar, honey trees, headbutt trees, contests, radio
 * channels, weekdays, Max Raid den rarity). Everything else (backlot slots,
 * item requirements, trade specifics, story flags…) stays stored but hidden.
 * Returns null for condition names that should not be displayed.
 */
export function prettyEncounterCondition(name: string): string | null {
  if (name.startsWith('weather-')) {
    const map: Record<string, string> = {
      'weather-normal': 'Any weather',
      'weather-fog': 'Fog',
      'weather-raining': 'Rain',
      'weather-thunderstorm': 'Thunderstorm',
      'weather-intense-sun': 'Intense sun',
      'weather-overcast': 'Overcast',
      'weather-snowing': 'Snowing',
      'weather-snowstorm': 'Snowstorm',
      'weather-sandstorm': 'Sandstorm',
      'weather-drought': 'Drought',
      'weather-rainstorm': 'Rainstorm',
    };
    return (
      map[name] ||
      name
        .replace('weather-', '')
        .split('-')
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ')
    );
  }
  const exact: Record<string, string> = {
    'time-day': 'Daytime',
    'time-morning': 'Morning',
    'time-evening': 'Evening',
    'time-night': 'Night',
    'season-spring': 'Spring',
    'season-summer': 'Summer',
    'season-autumn': 'Autumn',
    'season-winter': 'Winter',
    'swarm-yes': 'Swarm',
    'radar-on': 'Poké Radar',
    'bug-catching-contest-yes': 'Bug-Catching Contest',
    'radio-hoenn': 'Hoenn Sound radio',
    'radio-sinnoh': 'Sinnoh Sound radio',
    'pla-alpha': 'Alpha form',
    'pla-mass-outbreak': 'Mass Outbreak',
    'sv-mass': 'Mass outbreak nearby',
  };
  if (exact[name]) return exact[name];
  if (name.startsWith('sv-biome-')) {
    const biome = name.replace('sv-biome-', '').split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    return `Biome: ${biome}`;
  }
  const prefix = (p: string, fmt: (rest: string) => string): string | null =>
    name.startsWith(p) ? fmt(name.slice(p.length)) : null;
  return (
    prefix('honey-tree-group-', (r) => `Honey tree (group ${r.toUpperCase()})`) ||
    prefix('headbutt-tree-', (r) => `Headbutt tree (${r})`) ||
    prefix('weekday-', (r) => `${r.charAt(0).toUpperCase() + r.slice(1)}s only`) ||
    prefix('max-den-rarity-', (r) => `Max Den (${r})`) ||
    prefix('max-den-rating-', (r) => `Max Den ${r.replace('-star', '★')}`) ||
    null
  );
}

export function prettyEncounterMethod(method: string): string {
  const map: Record<string, string> = {
    walk: 'Walking in grass',
    surf: 'Surfing',
    'old-rod': 'Old Rod fishing',
    'good-rod': 'Good Rod fishing',
    'super-rod': 'Super Rod fishing',
    'older-rod': 'Old Rod fishing',
    gift: 'Gift',
    'gift-egg': 'Received as Egg',
    trade: 'In-game trade',
    'level-up': 'Level-up spawn',
    'radio-east': 'Pokégear radio (east)',
    'radio-west': 'Pokégear radio (west)',
    'swarm': 'Swarm',
    headbutt: 'Headbutt tree',
    'headbutt-special': 'Headbutt tree (special)',
    'hidden-grotto': 'Hidden Grotto',
    'in-sky': 'Encountered in sky',
    'bug-contest': 'Bug-Catching Contest',
    'grass-special': 'Grass (special)',
    'grass-dark': 'Grass (dark patch)',
  };
  return (
    map[method] ||
    method
      .split('-')
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ')
  );
}

/** Fetch + cache the dataset for components. */
export function useEncounterDataset(): { dataset: EncounterDataset | null; loading: boolean } {
  const [dataset, setDataset] = useState<EncounterDataset | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    loadEncounterDataset().then((data) => {
      if (alive) {
        setDataset(data);
        setLoading(false);
      }
    });
    return () => {
      alive = false;
    };
  }, []);

  return { dataset, loading };
}
